// Chốt expected trước chạy; FAIL chỉ ghi bằng chứng, không sửa sản phẩm trong lượt.
internal sealed class AcceptanceProbe(ConnectionFactory factory,SqlConnection owner,PermissionService permissions,SessionContext admin,string output)
{
    private sealed record Case(string Id,string Expected,string Actual,string Status);
    private readonly List<Case> cases=[];
    private readonly AssetService assets=new(new AssetRepository(factory),permissions);
    private readonly ReportService reports=new(new ReportRepository(factory),permissions);
    private readonly DateOnly today=DateOnly.FromDateTime(DateTime.Today);
    public async Task<object> Run()
    {
        try{await Assets();await Reports();await Reconcile();await RaceProbe.Run(factory,owner,permissions,admin,r=>{cases.Add(new(r.Id,r.Expected,r.Actual,r.Status));Save();});await Artifacts();}
        catch(Exception e){cases.Add(new("FixtureSetup","Fixture đủ để chạy các phần sau",e.ToString(),"BLOCKED"));}
        finally{Save();}
        return new{Executed=cases.Count,Passed=cases.Count(c=>c.Status=="PASS"),Failed=cases.Count(c=>c.Status=="FAIL"),Blocked=cases.Count(c=>c.Status=="BLOCKED"),File=Path.GetFileName(output)};
    }
    private void Save()=>File.WriteAllText(output,JsonSerializer.Serialize(cases,new JsonSerializerOptions{WriteIndented=true}));
    private async Task Check(string id,string expected,Func<Task<object?>> test){try{var value=await test();cases.Add(new(id,expected,JsonSerializer.Serialize(value,value?.GetType()??typeof(object)),"PASS"));}catch(Exception e){cases.Add(new(id,expected,e.ToString(),"FAIL"));}Save();}
    private static void Assert(bool valid,string message){if(!valid)throw new InvalidOperationException(message);}
    private static async Task<int> Error(Func<Task> action){try{await action();return 0;}catch(UserOperationException e){return e.Error.Number;}catch(SqlException e){return e.Number;}catch(ArgumentException){return -1;}}
    private async Task<AssetRow> Create(decimal value=100,int months=3){var saved=await assets.WriteAsync(admin,new(Guid.NewGuid(),"Create",null,null,new("Tài sản nghiệm thu",today,value,months)));return (await assets.GetAsync(admin,saved.Code))!;}
    private async Task Assets()
    {
        var count=Convert.ToInt32(await Scalar("SELECT COUNT(*) FROM dbo.PHIEUTHUCHI"));var row=await Create();
        await Check("T27-K01.create-update-reload","Tên Việt100ký tự, giá101 và revision mới",async()=>{var previous=row;var prefix="Máy pha cà phê ";await assets.WriteAsync(admin,new(Guid.NewGuid(),"Update",row.Code,row.Revision,new(prefix+new string('a',100-prefix.Length),new(2026,1,15),101,3)));row=(await assets.GetAsync(admin,row.Code))!;Assert(row.Name.Length==100&&row.Value==101&&!row.Revision.SequenceEqual(previous.Revision),"Asset update mismatch");return row;});
        await Check("T27-K03.no-expense","Lưu hồ sơ không sinh chi",async()=>{var after=Convert.ToInt32(await Scalar("SELECT COUNT(*) FROM dbo.PHIEUTHUCHI"));Assert(count==after,"Asset created expense");return new{Before=count,After=after};});
        foreach(var (value,months) in new[]{(0m,3),(-1m,3),(1.1m,3),(1000000000000000000m,3),(1m,0),(1m,-1)}){
            await Check($"T27-K02.BLL-{value}-{months}","Input sai bị BLL chặn",async()=>{var e=await Error(async()=>{await assets.WriteAsync(admin,new(Guid.NewGuid(),"Create",null,null,new("Biên",today,value,months)));});Assert(e==-1,"Expected argument error");return e;});
            await Check($"T27-K02.SQL-{value}-{months}","SQL53401 và transaction trước/sau bằng nhau",async()=>{await using var c=await Runtime();var before=await State(c);var e=await Invalid(c,"Biên",value,months);var after=await State(c);Assert(e==53401&&before==after,"SQL validation/transaction mismatch");return new{e,before,after};});
        }
        foreach(var name in new[]{"","   ",new string('x',101)})await Check("T27-K02.name-"+name.Length,"SQL chặn tên rỗng/quá dài",async()=>{await using var c=await Runtime();var e=await Invalid(c,name,1,3);Assert(e==53401,"Name accepted");return e;});
        await Check("T27-K02.max-money-intmax","Max18 chữ số/intmax tháng giữ chính xác",async()=>{var r=await Create(999999999999999999m,int.MaxValue);Assert(r.Value==999999999999999999m&&r.Months==int.MaxValue,"Precision lost");return r;});
        foreach(var (value,months,asOf) in new[]{(100m,3,new DateOnly(2025,12,31)),(100m,3,new DateOnly(2026,1,1)),(100m,3,new DateOnly(2026,3,1)),(100m,3,new DateOnly(2026,4,1)),(1m,3,new DateOnly(2026,3,1)),(999999999999999999m,int.MaxValue,new DateOnly(9999,12,31))}){
            await Check("T27-K05-K06.parity-"+asOf+"-"+value,"SQL và calculator bằng nhau, lũy kế≤nguyên giá",async()=>{var purchase=new DateOnly(2026,1,15);var expected=AssetDepreciationCalculator.Calculate(value,months,purchase,asOf);await using var cmd=owner.CreateCommand();cmd.CommandText="SELECT Monthly,Accumulated FROM dbo.fn_AssetDepreciation(@v,@m,@p,@d)";cmd.Parameters.AddWithValue("@v",value);cmd.Parameters.AddWithValue("@m",months);cmd.Parameters.AddWithValue("@p",purchase.ToDateTime(TimeOnly.MinValue));cmd.Parameters.AddWithValue("@d",asOf.ToDateTime(TimeOnly.MinValue));await using var r=await cmd.ExecuteReaderAsync();await r.ReadAsync();var monthly=r.GetDecimal(0);var accumulated=r.GetDecimal(1);Assert(monthly==expected.Monthly&&accumulated==expected.Accumulated&&accumulated<=value,"Depreciation mismatch");return new{monthly,accumulated};});
        }
        var request=new AssetWriteRequest(Guid.NewGuid(),"Create",null,null,new("Replay",today,100,3));var receipt=await assets.WriteAsync(admin,request);
        await Check("T27-K09.replay","Cùngrequest cùngcode; payload khác51608",async()=>{var replay=await assets.WriteAsync(admin,request);var e=await Error(async()=>{await assets.WriteAsync(admin,request with{Value=request.Value! with{Value=101}});});Assert(replay.Code==receipt.Code&&(await assets.ReceiptAsync(admin,request.RequestId))?.Code==receipt.Code&&e==51608,"Replay mismatch");return new{replay.Code,e};});
        await Check("T27-K01.empty-page-total","Trang rỗng vẫn trả tổng thật",async()=>{var p=await assets.ListAsync(admin,new("",100000));Assert(p.Rows.Count==0&&p.TotalCount>0,"Page metadata mismatch");return new{p.TotalCount,Rows=p.Rows.Count};});
        await Check("T27-K08.delete-version","Version cũ53403, version mới xóa được nếu chưa tham chiếu",async()=>{var r=await Create();await assets.WriteAsync(admin,new(Guid.NewGuid(),"Update",r.Code,r.Revision,new(r.Name,today,200,3)));var stale=await Error(async()=>{await assets.WriteAsync(admin,new(Guid.NewGuid(),"Delete",r.Code,r.Revision,null));});r=(await assets.GetAsync(admin,r.Code))!;await assets.WriteAsync(admin,new(Guid.NewGuid(),"Delete",r.Code,r.Revision,null));Assert(stale==53403&&await assets.GetAsync(admin,r.Code) is null,"Delete mismatch");return stale;});
        var finance=new FinanceService(new FinanceRepository(factory),permissions);var category=(await finance.CategoriesAsync(admin)).First(c=>c.Type=="Chi");var linked=await Create(85000000,60);var expense=await finance.CreateAsync(admin,new(Guid.NewGuid(),Now(),category.Code,500000,"Chi sửa chữa",linked.Code));
        await Check("T27-K04-K08.expense-source","Một chi500.000 đúngMaTS, xóa53402",async()=>{var p=await assets.ExpensesAsync(admin,linked.Code,today,today);var e=await Error(async()=>{await assets.WriteAsync(admin,new(Guid.NewGuid(),"Delete",linked.Code,linked.Revision,null));});Assert(p.TotalAmount==500000&&p.TotalCount==1&&(await finance.GetAsync(admin,expense))?.AssetCode==linked.Code&&e==53402,"Expense link mismatch");return new{p.TotalAmount,e};});
        await Check("T27-K02.invalid-expense-asset","MaTS không tồn tại52602, không sinh phiếu/receipt",async()=>{var before=Convert.ToInt32(await Scalar("SELECT COUNT(*) FROM dbo.PHIEUTHUCHI"));var id=Guid.NewGuid();var e=await Error(async()=>{await finance.CreateAsync(admin,new(id,Now(),category.Code,1,"G07 invalid asset","TS999"));});Assert(e==52602&&before==Convert.ToInt32(await Scalar("SELECT COUNT(*) FROM dbo.PHIEUTHUCHI"))&&await finance.ReconcileAsync(admin,id) is null,"Invalid asset linked");return e;});
        await Check("T27-K08.concurrent-version","Hai session cùngrevision: chỉ1update thắng,1lỗi53403",async()=>{var r=await Create();var requests=new[]{new AssetWriteRequest(Guid.NewGuid(),"Update",r.Code,r.Revision,new("RaceA",today,201,3)),new AssetWriteRequest(Guid.NewGuid(),"Update",r.Code,r.Revision,new("RaceB",today,202,3))};var outcomes=await Task.WhenAll(requests.Select(async q=>await Error(async()=>{await assets.WriteAsync(admin,q);})));var actual=(await assets.GetAsync(admin,r.Code))!;Assert(outcomes.Count(e=>e==0)==1&&outcomes.Count(e=>e==53403)==1&&actual.Value is 201 or 202,"Concurrent update lost revision guard");return new{outcomes,actual.Value};});
        for(int iteration=0;iteration<10;iteration++)await Check("T27-K08.concurrent-delete-expense-"+(iteration+1),"Hai session xóa/ghi chi: một kết quả hợp lệ, không orphan/ghi dở",async()=>{
            var r=await Create();var id=Guid.NewGuid();using var hold=owner.BeginTransaction();await using(var locked=owner.CreateCommand()){locked.Transaction=hold;locked.CommandText="SELECT GiaTri FROM dbo.TAISAN_CODINH WITH(XLOCK,HOLDLOCK) WHERE MaTS=@c";locked.Parameters.AddWithValue("@c",r.Code);await locked.ExecuteScalarAsync();}
            var deletion=Error(async()=>{await assets.WriteAsync(admin,new(Guid.NewGuid(),"Delete",r.Code,r.Revision,null));});var expenseWrite=Error(async()=>{await finance.CreateAsync(admin,new(id,Now(),category.Code,7,"G07 race chi",r.Code));});int waiters=0;
            try{for(int i=0;i<80;i++){await using var observe=owner.CreateCommand();observe.Transaction=hold;observe.CommandText="SELECT COUNT(*) FROM sys.dm_exec_requests WHERE database_id=DB_ID() AND session_id<>@@SPID AND wait_type LIKE 'LCK_M%'";waiters=Convert.ToInt32(await observe.ExecuteScalarAsync());if(waiters>=2)break;await Task.Delay(100);}}finally{hold.Rollback();}
            var outcomes=await Task.WhenAll(deletion,expenseWrite);var actual=await assets.GetAsync(admin,r.Code);var source=await finance.ReconcileAsync(admin,id);Assert(waiters>=2&&(outcomes[0]==0&&outcomes[1]==52602&&actual is null&&source is null||outcomes[0]==53402&&outcomes[1]==0&&actual is not null&&source is not null),"Invalid delete/expense race: "+string.Join(',',outcomes));return new{waiters,outcomes,Exists=actual is not null,Expense=source};
        });
        foreach(var role in new[]{"CASH","STORE"}){
            using var actor=await Role(role);await Check("T27-K09.role-"+role,"BLL/SQL chặn role bằng51605",async()=>{var bll=await Error(async()=>{await assets.ListAsync(actor,new());});await using var c=await Runtime();await using var cmd=c.CreateCommand();cmd.CommandText="EXEC dbo.sp_AssetList @Actor=@a,@Stamp=@s";Actor(cmd,actor);var sql=await Error(async()=>{await cmd.ExecuteNonQueryAsync();});Assert(bll==51605&&sql==51605,"Role escaped");return new{bll,sql};});
            foreach(var kind in Enum.GetValues<ReportKind>())await Check("T28-K12."+role+"-"+kind,"BLL chặn mọi report",async()=>{var e=await Error(async()=>{await reports.ReadAsync(actor,new(kind,today,today));});Assert(e==51605,"Report role escaped");return e;});
            foreach(var endpoint in new[]{"Sales","Products","Payments","Inventory","Debts","CashFlow","Labor","Assets","Dashboard","Options","SourceList"})await Check("T28-K12.SQL-"+role+"-"+endpoint,"SQL endpoint chặn51605",async()=>{await using var c=await Runtime();await using var cmd=c.CreateCommand();cmd.CommandText="EXEC dbo.sp_Report"+endpoint+" @Actor=@a,@Stamp=@s"+(endpoint is "Dashboard" or "Options"?"":",@From='20260101',@To='20261231'")+(endpoint=="SourceList"?",@Kind='Assets',@GroupCode='TS001'":"");Actor(cmd,actor);var e=await Error(async()=>{await cmd.ExecuteNonQueryAsync();});Assert(e==51605,"SQL report role escaped");return e;});
            await Check("T28-K12.extras-"+role,"BLL options/dashboard/source đều51605",async()=>{var a=await Error(async()=>{await reports.OptionsAsync(actor);});var b=await Error(async()=>{await reports.DashboardAsync(actor);});var c=await Error(async()=>{await reports.SourcesAsync(actor,new(ReportKind.Assets,today,today),"TS001");});Assert(a==51605&&b==51605&&c==51605,"BLL extras leaked");return new{a,b,c};});
        }
        await Check("T27-K09.fault-rollback","Fault không để asset/receipt dở",async()=>{var id=Guid.NewGuid();await Execute("CREATE TRIGGER dbo.TR_G07FaultAsset ON dbo.TAISAN_CODINH AFTER INSERT AS THROW 54990,N'G07 injected fault',1;");try{var before=Convert.ToInt32(await Scalar("SELECT COUNT(*) FROM dbo.TAISAN_CODINH"));var e=await Error(async()=>{await assets.WriteAsync(admin,new(id,"Create",null,null,new("Fault",today,1,1)));});Assert(e!=0&&before==Convert.ToInt32(await Scalar("SELECT COUNT(*) FROM dbo.TAISAN_CODINH"))&&await assets.ReceiptAsync(admin,id) is null,"Partial write after fault");return e;}finally{await Execute("DROP TRIGGER dbo.TR_G07FaultAsset");}});
    }
