        foreach(var code in new[]{"NVL98","NVL99"}){var made=await materials.SaveAsync(admin,new(code,"Nguyên liệu G07 "+code,"g"),null,Guid.NewGuid());await materials.OpenAsync(admin,new(code,code=="NVL99"?200:0,"Fixture G07"),made.Revision!,Guid.NewGuid());}
        // Mốc lịch sử synthetic chuẩn bị trước ca, chỉ trong DBtest có marker.
        await Execute("UPDATE dbo.MaterialOpening SET RecordedAt=DATEADD(day,-1,CONVERT(date,SYSDATETIME())) WHERE MaNVL IN('NVL98','NVL99')");
        await products.SaveAsync(admin,new("SP900","Món G07 snapshot","DM001",12345,"Dang ban",[new("NVL99",1)]),null,Guid.NewGuid());await products.SaveAsync(admin,new("SP901","Món G07 race","DM001",100,"Dang ban",[new("NVL98",1)]),null,Guid.NewGuid());
