        await Check("T28-K03.multi-line-payment","2dòng×2TT: món24.690/lượng2, TTkhớp",async()=>{var p=await reports.ReadAsync(admin,new(ReportKind.Products,today,today));var r=p.Rows.Cast<ProductReportRow>().Single(x=>x.Code=="SP900");var paid=(await sales.GetAsync(admin,bill))!;Assert(r.BeforeBillDiscount==24690&&r.Quantity==2&&paid.Payments.Sum(x=>x.Amount)==24690,"Double counted");return r;});
