        await Check("T28-K01-K05.paid-date-last-second","HD20259999 25.000 ở02/04/2025 23:59:59; không ở ngày lập01/04 hay ngày kế03/04",async()=>{const string code="HD20259999";var paidDay=new DateOnly(2025,4,2);var included=await reports.SourcesAsync(admin,new(ReportKind.SalesDay,paidDay,paidDay),"2025-04-02");var excluded=await reports.SourcesAsync(admin,new(ReportKind.SalesDay,new(2025,4,1),new(2025,4,1)),"2025-04-01");var next=await reports.SourcesAsync(admin,new(ReportKind.SalesDay,new(2025,4,3),new(2025,4,3)),"2025-04-03");Assert(included.Rows.Single(x=>x.Code==code).Amount==25000&&!excluded.Rows.Any(x=>x.Code==code)&&!next.Rows.Any(x=>x.Code==code),"Paid date boundary mismatch");return new{Code=code,included.TotalCount};});
