        await Check("T28-K06.database-error","Lỗi EXECUTE bị từ chối trả lỗi229, không thành report0",async()=>{await Execute("DENY EXECUTE ON dbo.sp_ReportAssets TO G07Runtime");try{var e=await Error(async()=>{await reports.ReadAsync(admin,new(ReportKind.Assets,today,today));});Assert(e==229,"Permission error became success or wrong error");return e;}finally{await Execute("REVOKE EXECUTE ON dbo.sp_ReportAssets TO G07Runtime");}});
