    private Task Artifacts()=>Check("T29-K01-K04.artifacts","Lượt10.000bill đầy đủ, source không đổi/DBđãdọn và actualplan",()=>{var dir=new DirectoryInfo(AppContext.BaseDirectory);while(dir is not null&&!File.Exists(Path.Combine(dir.FullName,"CafeManager.slnx")))dir=dir.Parent;var run=Path.Combine(dir!.FullName,"docs/tasks/g07-tai-san-bao-cao-hieu-nang-du-lieu/runs/performance_20261031_103410_dbbb420d");using var json=JsonDocument.Parse(File.ReadAllText(Path.Combine(run,"manifest.json")));Assert(json.RootElement.GetProperty("Status").GetString()=="Succeeded"&&json.RootElement.GetProperty("SourceUnchanged").GetBoolean()&&json.RootElement.GetProperty("Cleaned").GetBoolean()&&Directory.GetFiles(run,"*.sqlplan").Length==230,"Invalid benchmark evidence");return Task.FromResult<object?>(new{ActualPlans=230,Artifact=Path.GetFileName(run)});});
    private async Task<SessionContext> Role(string role){var employees=new EmployeeService(new EmployeeRepository(factory),permissions);var accounts=new EmployeeAccountService(new EmployeeAccountRepository(factory),permissions,new PasswordService());var code=await employees.SaveAsync(admin,new("Role "+role,null,"Part-time",0,30000,"CV002"),null,Guid.NewGuid());var password=Guid.NewGuid().ToString("N");await accounts.WriteAsync(admin,"Create",new(code,null,"g07."+role.ToLowerInvariant(),role,true),password,password,Guid.NewGuid());var row=(await employees.GetAsync(admin,code))!;return new((await new AuthRepository(factory).ReadIdentityAsync(row.AccountId!.Value,default))!);}
    private async Task Reconcile()
    {
        await Check("T28-K10.overnight-incomplete","Ca22h→06h là8giờ; ca chưa ra ghi1incomplete, không tự tính lương/chi",async()=>{
            var catalogs=new CatalogService(new CatalogRepository(factory),permissions);await catalogs.SaveAsync(admin,new CafeManager.Models.Requests.Catalogs.ShiftRequest("CA998","G07 qua đêm",TimeSpan.FromHours(22),TimeSpan.FromHours(6)),null);
            var worker=await new EmployeeService(new EmployeeRepository(factory),permissions).SaveAsync(admin,new("G07 ca đêm",null,"Part-time",0,35000,"CV002"),null,Guid.NewGuid());var day=DateTime.Today.AddDays(-2);
