            Assert(a.Gross-b.Gross==54321&&a.Discount-b.Discount==5432&&a.Ship-b.Ship==5000&&a.Amount-b.Amount==53889&&a.Fees-b.Fees==2444,"Report deltas differ");return new{before.Totals,After=a,Code=code};
        });
        await Check("T28-K08.cash-sources","Thu khác73; chi khác31 + nhập trả ngay30 + trả nợ20 =81, không chi thêm từ bảng liên kết",async()=>{
