            var unpaid=(LaborReportRow)(await reports.ReadAsync(admin,new(ReportKind.Labor,today,today,Employee:worker))).Rows.Single();var hours=(LaborReportRow)(await reports.ReadAsync(admin,new(ReportKind.Labor,today.AddDays(-1),today.AddDays(-1),Employee:worker))).Rows.Single();
