    private async Task<SqlConnection> Runtime(){var c=new SqlConnection(new SqlConnectionStringBuilder(owner.ConnectionString){Pooling=false}.ConnectionString);await c.OpenAsync();await using var cmd=c.CreateCommand();cmd.CommandText="EXECUTE AS USER='G07Runtime'";await cmd.ExecuteNonQueryAsync();return c;}
    private static void Actor(SqlCommand cmd,SessionContext actor){cmd.Parameters.AddWithValue("@a",actor.Identity.AccountId);cmd.Parameters.Add("@s",SqlDbType.Binary,8).Value=actor.Identity.SecurityStamp;}
    private async Task<int> Invalid(SqlConnection c,string name,decimal value,int months){await using var cmd=c.CreateCommand();cmd.CommandText="EXEC dbo.sp_AssetWrite @Actor=1,@Stamp=@s,@Action='Create',@RequestId=@id,@Name=@n,@PurchasedOn='20260101',@Value=@v,@Months=@m";cmd.Parameters.Add("@s",SqlDbType.Binary,8).Value=admin.Identity.SecurityStamp;cmd.Parameters.AddWithValue("@id",Guid.NewGuid());cmd.Parameters.Add("@n",SqlDbType.NVarChar,-1).Value=name;cmd.Parameters.Add(new SqlParameter("@v",SqlDbType.Decimal){Precision=38,Scale=18,Value=new SqlDecimal(value)});cmd.Parameters.AddWithValue("@m",months);return await Error(async()=>{await cmd.ExecuteNonQueryAsync();});}
    private static async Task<string> State(SqlConnection c){await using var cmd=c.CreateCommand();cmd.CommandText="SELECT CONCAT(@@TRANCOUNT,':',XACT_STATE())";return (string)(await cmd.ExecuteScalarAsync())!;}
    private async Task<object?> Scalar(string sql){await using var cmd=owner.CreateCommand();cmd.CommandText=sql;return await cmd.ExecuteScalarAsync();}
    private async Task Execute(string sql){await using var cmd=owner.CreateCommand();cmd.CommandText=sql;await cmd.ExecuteNonQueryAsync();}
    private static DateTime Now(){var n=DateTime.Now;return n.AddTicks(-(n.Ticks%TimeSpan.TicksPerSecond));}
}
